diff --git a/src/libcamera/egl.cpp b/src/libcamera/egl.cpp
index b3d3b9abb..ff9e54a19 100644
--- a/src/libcamera/egl.cpp
+++ b/src/libcamera/egl.cpp
@@ -184,7 +184,7 @@ int eGL::createDMABufTexture2D(eGLImage &eglImage, int fd, bool output)
 		drm_format = DRM_FORMAT_R8;
 		break;
 	case GL_RG:
-		drm_format = DRM_FORMAT_RG88;
+		drm_format = DRM_FORMAT_GR88;
 		break;
 	case GL_RGBA:
 		drm_format = DRM_FORMAT_ARGB8888;

before_statements.quote:
switch (eglImage.format_) {
	case GL_RED:
	case GL_LUMINANCE:
		drm_format = DRM_FORMAT_R8;
		break;
	case GL_RG:
		drm_format = DRM_FORMAT_RG88;
		break;
	case GL_RGBA:
		drm_format = DRM_FORMAT_ARGB8888;
		break;
	default:
		LOG(eGL, Error) << "unhandled GL format";
		return -ENODEV;
	}

switch (eglImage.format_) {
	case GL_RED:
